-- Money: the curated cascade stacks listen with Azure Speech, not Gemini (Vertex has no Gemini transcription model;
-- decision.2026-10-22.ears-azure-not-gemini). The Gemini ears rows go inactive and the Azure ears rows come in, as
-- generated by server/modules/money/prices.ts computeCard() (tests/money.test.ts checks there is no drift).
UPDATE cost_card SET active = false WHERE component = 'ears' AND provider = 'Gemini 3.5 transcribe-live' AND active;
;
